commands.command:
set -eu; TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT; adb exec-out run-as io.blueeye cat databases/tracker_database > "$TMP/db"; adb exec-out run-as io.blueeye cat databases/tracker_database-wal > "$TMP/db-wal" 2>/dev/null || true; adb exec-out run-as io.blueeye cat databases/tracker_database-shm > "$TMP/db-shm" 2>/dev/null || true; python3 - "$TMP/db" <<'PY'
import sqlite3,sys,re,statistics,collections
p=sys.argv[1]
c=sqlite3.connect(p)
mx=c.execute('select coalesce(max(timestamp),0) from signal_samples').fetchone()[0]
start=mx-15*60*1000
rows=c.execute("select deviceFingerprint,observedMac,coalesce(deviceName,''),coalesce(deviceType,''),coalesce(beaconType,''),rssi,timestamp,coalesce(serviceDataByUuidHex,''),coalesce(trackingStatus,''),coalesce(followingScore,0) from signal_samples where timestamp>=? and (lower(coalesce(beaconType,'')) like '%find hub%' or lower(coalesce(serviceDataByUuidHex,'')) like '%feaa%=40%' or lower(coalesce(serviceDataByUuidHex,'')) like '%feaa%=41%') order by timestamp",(start,)).fetchall()
by=collections.OrderedDict()
for r in rows: by.setdefault(r[0],[]).append(r)
print('WINDOW_MINUTES=15')
print('FHN_ROWS=%d DISTINCT_FINGERPRINTS=%d' % (len(rows),len(by)))
for i,(fp,rs) in enumerate(by.items(),1):
    rss=[x[5] for x in rs]; macs={x[1] for x in rs if x[1]}; payloads=set(); frames=collections.Counter(); names=collections.Counter(x[2] for x in rs if x[2]); types=collections.Counter(x[3] for x in rs if x[3]); beacons=collections.Counter(x[4] for x in rs if x[4]); statuses=collections.Counter(x[8] for x in rs if x[8]); scores=[float(x[9]) for x in rs]
    for x in rs:
        m=re.search(r'feaa[^=]*=([0-9a-fA-F]+)',x[7],re.I)
        if m:
            h=m.group(1).upper(); payloads.add(h); frames[h[:2] if len(h)>=2 else '']=frames.get(h[:2] if len(h)>=2 else '',0)+1
    span=(rs[-1][6]-rs[0][6])/1000
    print('FHN%d samples=%d span_s=%.1f median_rssi=%.1f min_rssi=%d max_rssi=%d mac_count=%d payload_count=%d frames=%s names=%s types=%s beacons=%s statuses=%s score_max=%.1f' % (i,len(rs),span,statistics.median(rss),min(rss),max(rss),len(macs),len(payloads),dict(frames),dict(names),dict(types),dict(beacons),dict(statuses),max(scores) if scores else 0))
# Temporal coexistence in 2-second bins without exposing identifiers
fps=list(by)
if len(fps)>1:
  sets={fp:{int(r[6]//2000) for r in by[fp]} for fp in fps}
  for i in range(len(fps)):
    for j in range(i+1,len(fps)):
      inter=len(sets[fps[i]] & sets[fps[j]]); union=len(sets[fps[i]] | sets[fps[j]])
      print('PAIR FHN%d-FHN%d shared_2s_bins=%d union_2s_bins=%d jaccard=%.3f' % (i+1,j+1,inter,union,inter/union if union else 0))
sony=c.execute("select coalesce(deviceName,''),coalesce(deviceType,''),coalesce(vendorName,''),rssi,timestamp from signal_samples where timestamp>=? and (lower(coalesce(deviceName,'')) like '%wf-1000xm5%' or lower(coalesce(vendorName,'')) like '%sony%') order by timestamp",(start,)).fetchall()
print('SONY_ROWS=%d' % len(sony))
if sony:
  print('SONY_NAMES=%s MEDIAN_RSSI=%.1f' % (dict(collections.Counter(x[0] for x in sony)),statistics.median([x[3] for x in sony])))
# Current device state for FHN aliases only; no raw fingerprint/MAC output
for i,(fp,_) in enumerate(by.items(),1):
  d=c.execute("select coalesce(lastDeviceName,''),coalesce(deviceType,''),coalesce(beaconType,''),coalesce(trackingStatus,''),coalesce(followingScore,0),coalesce(isPaired,0),coalesce(isIgnoredForTracking,0),coalesce(calibrationLabel,'') from devices where fingerprint=?",(fp,)).fetchone()
  if d: print('FHN%d_DEVICE name=%r type=%s beacon=%r status=%s score=%.1f paired=%s ignored=%s calibration=%r' % (i,d[0],d[1],d[2],d[3],float(d[4]),d[5],d[6],d[7]))
PY
